args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==3)
out<-normalizePath(args[1]);candidate<-as.integer(args[2]);lib<-normalizePath(args[3])
.libPaths(c(lib,.libPaths()))
suppressPackageStartupMessages({library(Matrix);library(scSHC);library(jsonlite)})
plan<-fromJSON(file.path(out,'PREPARED.json'));stopifnot(file.exists(file.path(out,'RANKED.json')))
candidates<-read.csv(file.path(out,'scSHC_candidates.csv'));stopifnot(candidate %in% seq_len(nrow(candidates)))
r<-candidates$resolution[candidate];tag<-sprintf('r%.1f',r)
stopifnot(!file.exists(file.path(out,paste0('scSHC_',tag,'_COMPLETE.json'))))
mat<-as(readMM(gzfile(file.path(out,'hvg_counts_PRIVATE.mtx.gz'))),'CsparseMatrix')
rownames(mat)<-readLines(file.path(out,'features.txt'));colnames(mat)<-readLines(file.path(out,'barcodes_PRIVATE.txt'))
meta<-read.csv(file.path(out,'metadata_PRIVATE.csv'),row.names=1,check.names=FALSE)
assign<-read.csv(file.path(out,'resolution_assignments_PRIVATE.csv'),row.names=1,check.names=FALSE)
stopifnot(ncol(mat)==plan$cells,identical(colnames(mat),rownames(meta)),identical(rownames(meta),rownames(assign)),all(mat@x>=0),all(mat@x==round(mat@x)),length(unique(meta$run_id))==plan$runs)
original<-as.character(assign[[sprintf('leiden_r%.1f_seed42',r)]])
trace('test_split',where=asNamespace('scSHC'),print=FALSE,tracer=quote({cat('Testing split',length(ids1),'vs',length(ids2),'eligible cells;',length(unique(batch[c(ids1,ids2)])),'runs;',format(Sys.time()),'\n');flush.console()}))
begin<-Sys.time();RNGkind("L'Ecuyer-CMRG");set.seed(42)
cat('START',tag,length(unique(original)),format(Sys.time()),'\n');flush.console()
tested<-testClusters(data=mat,cluster_ids=original,batch=as.character(meta$run_id),var.genes=rownames(mat),alpha=.05,num_PCs=30,parallel=TRUE,cores=4)
stopifnot(length(tested[[1]])==plan$cells,!anyNA(tested[[1]]))
saveRDS(tested,file.path(out,paste0('scSHC_',tag,'_PRIVATE.RDS')))
write.csv(data.frame(cell=colnames(mat),leiden_cluster=original,scSHC_cluster=as.character(tested[[1]])),file.path(out,paste0('scSHC_',tag,'_labels_PRIVATE.csv')),row.names=FALSE)
write.csv(as.data.frame.matrix(table(original,tested[[1]])),file.path(out,paste0('scSHC_',tag,'_merge_table.csv')))
capture.output(print(tested[[2]]),file=file.path(out,paste0('scSHC_',tag,'_tree.txt')))
write_json(list(resolution=r,input_clusters=length(unique(original)),defended_clusters=length(unique(tested[[1]])),cells=plan$cells,elapsed_minutes=as.numeric(difftime(Sys.time(),begin,units='mins')),seed=42,RNG_kind=RNGkind(),alpha=.05,batch='run_id',PCs=30,cores=4,version=as.character(packageVersion('scSHC')),completed=as.character(Sys.time()),caveat='Splits need >20 cells per side within eligible runs; untestable rare/batch-specific splits can merge. This is not proof of biological identity.'),file.path(out,paste0('scSHC_',tag,'_COMPLETE.json')),pretty=TRUE,auto_unbox=TRUE)
cat('COMPLETE',tag,format(Sys.time()),'\n')
